        (function() {
    // SLA Breach Early Warning - Evaluate Cases
    // Checks open cases nearing SLA breach and sends notifications

    gs.info('SLA Breach Early Warning: Starting evaluation');

    // Find active task_sla records approaching breach (>= 75% elapsed)
    var taskSla = new GlideRecord('task_sla');
    taskSla.addQuery('active', 'true');
    taskSla.addQuery('has_breached', 'false');
    taskSla.addEncodedQuery('percentage>=75');
    taskSla.query();

    var notifiedCount = 0;

    while (taskSla.next()) {
        var taskId = taskSla.getValue('task');
        var percentage = taskSla.getValue('percentage');

        // Get the linked case
        var caseGr = new GlideRecord('sn_customerservice_case');
        if (!caseGr.get(taskId)) {
            continue;
        }

        // Only process cases in our scope with complaint_type
        var complaintType = caseGr.getValue('x_2145749_qc_complaint_type');
        if (!complaintType) {
            continue;
        }

        var caseNumber = caseGr.getValue('number');
        var darkStoreSysId = caseGr.getValue('x_2145749_qc_dark_store');
        var storeName = '';

        if (darkStoreSysId) {
            var storeGr = new GlideRecord('x_2145749_qc_dark_store');
            if (storeGr.get(darkStoreSysId)) {
                storeName = storeGr.getValue('store_name');
            }
        }

        // Send notification to ops_leadership
        gs.eventQueue('x_2145749_qc.sla_breach_warning', caseGr,
            'Case ' + caseNumber + ' is at ' + percentage + '% of SLA. Category: ' + complaintType + '. Store: ' + storeName,
            'x_2145749_qc.ops_leadership');

        notifiedCount++;
    }

    gs.info('SLA Breach Early Warning: Evaluation complete');
})();
    gs.info('SLA Breach Early Warning: Evaluation complete. Notified for ' + notifiedCount + ' cases.');
})();

